/* Conservative duplicate-payment review. Historical rows are read-only comparison data. */
const DuplicateCheck=(()=>{
 const norm=x=>String(x??'').normalize('NFKC').toLowerCase().replace(/\s+/g,'').trim();
 function hash(text){let a=2166136261,b=5381;for(let i=0;i<text.length;i++){a=Math.imul(a^text.charCodeAt(i),16777619);b=Math.imul(b,33)^text.charCodeAt(i)}return (a>>>0).toString(16)+(b>>>0).toString(16)}
 function projectNumber(value){const s=norm(value);const m=s.match(/(?:^|项目|编号)([一二两三四五六七八九十\d]+)(?![\dh]|小时)/);if(!m)return '';let n=m[1].replace(/两/g,'二');if(/^\d+$/.test(n))return String(Number(n));const digit=t=>'一二三四五六七八九'.indexOf(t)+1;if(n.includes('十')){const [t,u]=n.split('十');return String((t?digit(t):1)*10+(u?digit(u):0))}return String(digit(n))}
 function family(item,unit,rawType=''){
  const s=norm(item+' '+rawType);if(/辅助签约|签约成功/.test(s))return 'signing';if(/自产转介绍/.test(s))return 'referral';
  const hourly=unit==='小时'||(!/小项目|创意项目/.test(s)&&/\d(?:\.\d+)?(?:小时|h)|单课时|课时制/.test(s));
  if(hourly){const type=/软件|基础/.test(s)?'base':/思维/.test(s)?'thinking':/绘画/.test(s)?'drawing':/面试/.test(s)?'interview':'lesson';return 'hour-'+type}
  if(/排版/.test(s))return 'layout';if(/改版|视觉优化/.test(s))return 'revision';if(/视频/.test(s))return 'video';if(/面试/.test(s))return 'interview';if(/学习计划|研究计划|studyproposal|^sp$/.test(s))return 'study';if(/小项目|创意项目|artstudies/.test(s))return 'small';if(/项目|作品集|designproject/.test(s))return 'project';return 'other-'+norm(item||rawType);
 }
 function serviceProof(e){const raw=e.raw||{},text=[e.note,raw.note,raw.detail].filter(Boolean).join(' ');const dates=[...text.matchAll(/(?:20\d{2}[年./-])?\d{1,2}[月./-]\d{1,2}(?:日)?(?:\s*\d{1,2}[:：]\d{2}(?:\s*[-—~～至]\s*\d{1,2}[:：]\d{2})?)?/g)].map(m=>norm(m[0]).replace(/[年月.]/g,'-').replace(/日/g,''));return [...new Set(dates)].sort().join('|')}
 function baseCalculation(e,calc){if(/^疑似同一项目重复结算/.test(e.importIssue||''))return calc({...e,importIssue:''});return calc(e)}
 function describe(e,lookup,calc){if(e.duplicate||e.excludedReason)return null;if(e.history)return {...e,entry:e,signature:JSON.stringify([e.id,e.teacher,e.student,e.month,e.item,e.family,e.project,e.amount,e.proof,e.package])};const r=lookup(e.rule);if(!r)return null;const c=baseCalculation(e,calc);if(c.status!=='可结算'||!(c.amount>0))return null;const raw=e.raw||{},kind=(r.group||'').includes('签约')?'signing':family(r.item,r.unit,raw.type||'');return {id:e.id,entry:e,teacher:e.teacher,student:e.student,month:e.month,item:r.item,family:kind,project:projectNumber(e.project)||projectNumber(raw.project)||projectNumber(raw.type),proof:kind.startsWith('hour-')?serviceProof(e):'',package:[raw.country,raw.package,e.enrolledCourse].filter(Boolean).join(' / '),amount:c.amount,ratio:e.ratio,version:e.version,source:e.sourceLabel||'手动补录',signature:JSON.stringify([e.id,c.amount,e.teacher,e.student,e.month,e.version,e.rule,e.project,e.qty,e.ratio,e.paid,e.override,e.reason,e.fullPaid??raw.fullPaid,raw.country,raw.package,raw.signDate,raw.type,raw.note,raw.detail,e.note,e.signupShareCount,e.signupTeacherIndex])}}
 function scan(entries,history,month,lookup,calc){const unique=new Map(),sources=new Set();for(const e of entries){if(unique.has(e.id))continue;if(e.sourceKey&&sources.has(e.sourceKey))continue;unique.set(e.id,e);if(e.sourceKey)sources.add(e.sourceKey)}const groups=new Map();let hourlyUnproven=0;for(const e of [...unique.values(),...history]){const d=describe(e,lookup,calc);if(!d||!norm(d.teacher)||!norm(d.student))continue;if(d.family.startsWith('hour-')&&!d.proof){if(d.month===month&&!d.history)hourlyUnproven++;continue}const key=[norm(d.teacher),norm(d.student),d.family].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(d)}
  const pairs=[];let reviewed=0,limited=false;outer:for(const items of groups.values())for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i],b=items[j];if(a.history&&b.history)continue;if(![a,b].some(d=>!d.history&&d.month===month))continue;if(a.id===b.id)continue;
   if(a.family.startsWith('hour-')&&a.proof!==b.proof)continue;
   if(['project','small','layout','revision'].includes(a.family)&&a.project&&b.project&&a.project!==b.project)continue;
   const signatures=[a.signature,b.signature].sort(),token='dup-v1-'+hash(JSON.stringify(signatures));const reason=a.family.startsWith('hour-')?'同一老师、学生及授课日期 / 时间重复':a.family==='signing'?'同一老师对同一学生的辅助签约奖励再次出现':a.family==='referral'?'同一老师、学生的自产转介绍再次出现，请核对分次发放及累计上限':a.project&&b.project?'同一老师、学生、绩效类型及项目编号重复':'同一老师、学生、绩效类型再次出现，需核对项目或发放次数';
   const accepted=[a,b].some(d=>(d.entry.duplicateReviews||[]).some(r=>r.token===token&&r.reason));if(accepted){reviewed++;continue}pairs.push({token,a,b,reason:reason+([a,b].some(d=>d.ratio!==undefined&&d.ratio!==1)?'；含特殊比例，可能为分期结算':'' )});if(pairs.length>=500){limited=true;break outer}
  }return {pairs,reviewed,hourlyUnproven,limited};
 }
 function historyRows(book,month,fileName){const entries=[];let recognized=0,ignored=0;for(const sheet of book){let header=-1,map={},signing=false;for(let i=0;i<Math.min(60,sheet.rows.length);i++){const cells=sheet.rows[i].cells||[],at=names=>cells.findIndex(c=>names.includes(norm(c)));const m={teacher:at(['姓名','老师','负责老师','试听讲师']),student:at(['学生','学生姓名','试听学生']),item:at(['结算项目','绩效项目']),amount:at(['课酬','绩效金额','应发绩效','辅助签约奖励']),note:at(['备注']),month:at(['月份','结算月份']),project:at(['项目编号','编号']),package:at(['报名课程','学生套餐']),trial:at(['试听时间'])};if(m.teacher>=0&&m.student>=0&&m.amount>=0&&(m.item>=0||cells.some(c=>norm(c)==='辅助签约奖励'))){header=i;map=m;signing=cells.some(c=>norm(c)==='辅助签约奖励');break}}if(header<0)continue;recognized++;
   for(const row of sheet.rows.slice(header+1)){const value=k=>map[k]>=0?String(row.cells[map[k]]??'').trim():'',teacher=value('teacher'),student=value('student'),amount=Number(value('amount').replace(/[￥¥,，\s]/g,'')),item=signing?'辅助签约':value('item');if(!teacher||!student||!item||!Number.isFinite(amount)||amount<=0){ignored++;continue}const suppliedMonth=value('month'),period=suppliedMonth.match(/^(20\d{2})[-/年](\d{1,2})(?:月)?$/),recordMonth=period?period[1]+'-'+period[2].padStart(2,'0'):month;const id='history-'+hash(JSON.stringify([fileName,sheet.name,row.number,row.cells,recordMonth]));const note=value('note'),kind=signing?'signing':family(item,'',item);entries.push({id,history:true,teacher,student,month:recordMonth,item,family:kind,project:projectNumber(value('project'))||projectNumber(item),proof:kind.startsWith('hour-')?serviceProof({note}):'',package:value('package'),amount,note,source:fileName+' / '+sheet.name+' / 第'+row.number+'行'})}
  }if(!recognized||!entries.length)throw Error('未找到可核对的已发绩效明细。请使用含老师、学生、结算项目及金额的报表，工资汇总表无法逐条对比。');return {entries,ignored,recognized};
 }
 return {scan,describe,historyRows,family,projectNumber,hash};
})();
